      "lib/authorization.cash": "pragma cashscript ^0.14.0;\n\n// Grandma's Wallet shared authorization interface, v2.\n//\n// A protected output (wallet funds or an application position) is bound to a\n// wallet identity: the token category of the wallet's controller. It may only\n// be spent in a transaction that the current owner of that identity approves.\n//\n// Transaction layout:\n//   Inputs:  00-controller, 01+ protected inputs and anything else\n//   Outputs: 00-controller, 01+ anything\n//\n// A protected output holds no key and checks no signature. It requires that\n//   - input 0 is the wallet's controller, and\n//   - the controller continues with the same owner, epoch, recoverer and\n//     delay, and with no recovery claim pending.\n//\n// The controller is spent in the same transaction and enforces its own rules.\n// Only its owner-signed functions can produce that successor: a recovery\n// request leaves a claim pending and a completed recovery changes the owner\n// and epoch. The owner's signature, which the controller requires to cover\n// every input and output, is therefore what approves the protected spend.\n//\n// The presence of the controller alone is not treated as approval: the\n// recoverer can also spend it, to request or complete recovery, and neither\n// satisfies the second requirement.\n//\n// A controller that offered any way to reach that successor without the\n// owner's signature would break this interface. The version byte of the\n// state identifies the controller rules this version was written against.\nfunction ownerApproves(bytes32 identity) {\n    // The genuine controller: the identity NFT with mutable capability.\n    require(tx.inputs[0].tokenCategory == identity + 0x01);\n\n    bytes state = tx.inputs[0].nftCommitment;\n    require(state.length == 69);\n    require(state.split(1)[0] == 0x01);\n\n    require(tx.outputs[0].tokenCategory == identity + 0x01);\n    require(\n        tx.outputs[0].nftCommitment ==\n            0x0100 + state.slice(2, 49) + 0x0000000000000000000000000000000000000000\n    );\n}\n"
